     1→/**
     2→ * FreeLang Nexus - 통합 Parser
     3→ * V 모드 + Python 모드 함수를 혼합하여 파싱
     4→ */
     5→
     6→import { Token, TokenType } from '../lexer/token';
     7→import * as AST from './ast';
     8→
     9→export class NexusParser {
    10→  private tokens: Token[];
    11→  private pos: number = 0;
    12→
    13→  constructor(tokens: Token[]) {
    14→    this.tokens = tokens;
    15→  }
    16→
    17→  /**
    18→   * 파싱 진입점
    19→   */
    20→  parse(): AST.Program {
    21→    const body: Array<AST.VFunction | AST.PyFunction | AST.Statement> = [];
    22→
    23→    while (!this.isAtEnd()) {
    24→      this.skipNewlines();
    25→      if (this.isAtEnd()) break;
    26→
    27→      const token = this.peek();
    28→
    29→      // @mode 마커는 스킵 (이미 렉서에서 처리됨)
    30→      if (token.type === TokenType.MODE_MARKER) {
    31→        this.advance();
    32→        continue;
    33→      }
    34→
    35→      // 탑레벨 아이템 파싱
    36→      const item = this.parseTopLevel();
    37→      if (item) {
    38→        body.push(item);
    39→      }
    40→    }
    41→
    42→    return { type: 'Program', body };
    43→  }
    44→
    45→  /**
    46→   * 탑레벨 아이템 파싱
    47→   * V 함수, Python 함수, 또는 문장
    48→   */
    49→  private parseTopLevel(): AST.VFunction | AST.PyFunction | AST.Statement | null {
    50→    const token = this.peek();
    51→
    52→    // V 모드 함수
    53→    if (token.type === TokenType.FN) {
    54→      return this.parseVFunction();
    55→    }
    56→
    57→    // Python 모드 함수
    58→    if (token.type === TokenType.DEF) {
    59→      return this.parsePyFunction();
    60→    }
    61→
    62→    // 그 외: 문장
    63→    return this.parseStatement();
    64→  }
    65→
    66→  /**
    67→   * V 함수 파싱
    68→   * fn name(params) -> type { body }
    69→   */
    70→  private parseVFunction(): AST.VFunction {
    71→    const startToken = this.consume(TokenType.FN, 'fn 키워드 필요');
    72→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
    73→    const name = nameToken.value;
    74→
    75→    this.consume(TokenType.LPAREN, '( 필요');
    76→    const params = this.parseVParams();
    77→    this.consume(TokenType.RPAREN, ') 필요');
    78→
    79→    const returnType = this.parseReturnType();
    80→
    81→    this.consume(TokenType.LBRACE, '{ 필요');
    82→    const body = this.parseVBlock();
    83→    this.consume(TokenType.RBRACE, '} 필요');
    84→
    85→    return {
    86→      type: 'VFunction',
    87→      name,
    88→      params,
    89→      returnType,
    90→      body,
    91→      mode: 'v',
    92→      line: startToken.line,
    93→      column: startToken.column,
    94→    };
    95→  }
    96→
    97→  /**
    98→   * Python 함수 파싱
    99→   * def name(params): INDENT body DEDENT
   100→   */
   101→  private parsePyFunction(): AST.PyFunction {
   102→    const startToken = this.consume(TokenType.DEF, 'def 키워드 필요');
   103→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
   104→    const name = nameToken.value;
   105→
   106→    this.consume(TokenType.LPAREN, '( 필요');
   107→    const params = this.parsePyParams();
   108→    this.consume(TokenType.RPAREN, ') 필요');
   109→
   110→    const returnType = this.parseReturnType();
   111→
   112→    this.consume(TokenType.COLON, ': 필요');
   113→    this.skipNewlines();
   114→
   115→    const body = this.parsePyBlock();
   116→
   117→    return {
   118→      type: 'PyFunction',
   119→      name,
   120→      params,
   121→      returnType,
   122→      body,
   123→      mode: 'python',
   124→      line: startToken.line,
   125→      column: startToken.column,
   126→    };
   127→  }
   128→
   129→  /**
   130→   * V 함수 파라미터 파싱
   131→   * (x: i64, y: i64)
   132→   */
   133→  private parseVParams(): AST.Parameter[] {
   134→    const params: AST.Parameter[] = [];
   135→
   136→    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
   137→      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
   138→      this.consume(TokenType.COLON, ': 필요');
   139→      const typeToken = this.peek();
   140→      const typeAnnotation = this.parseType();
   141→
   142→      params.push({
   143→        name: nameToken.value,
   144→        typeAnnotation,
   145→        line: nameToken.line,
   146→        column: nameToken.column,
   147→      });
   148→
   149→      if (!this.check(TokenType.RPAREN)) {
   150→        this.consume(TokenType.COMMA, ', 필요');
   151→      }
   152→    }
   153→
   154→    return params;
   155→  }
   156→
   157→  /**
   158→   * Python 함수 파라미터 파싱
   159→   * (x, y) 또는 (x: int, y: int)
   160→   */
   161→  private parsePyParams(): AST.Parameter[] {
   162→    const params: AST.Parameter[] = [];
   163→
   164→    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
   165→      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
   166→      let typeAnnotation: string | undefined;
   167→
   168→      // 타입 어노테이션 (선택)
   169→      if (this.check(TokenType.COLON)) {
   170→        this.advance();
   171→        typeAnnotation = this.parseType();
   172→      }
   173→
   174→      params.push({
   175→        name: nameToken.value,
   176→        typeAnnotation,
   177→        line: nameToken.line,
   178→        column: nameToken.column,
   179→      });
   180→
   181→      if (!this.check(TokenType.RPAREN)) {
   182→        this.consume(TokenType.COMMA, ', 필요');
   183→      }
   184→    }
   185→
   186→    return params;
   187→  }
   188→
   189→  /**
   190→   * 반환 타입 파싱
   191→   * -> i64 (선택)
   192→   */
   193→  private parseReturnType(): string | undefined {
   194→    if (this.match(TokenType.ARROW)) {
   195→      return this.parseType();
   196→    }
   197→    return undefined;
   198→  }
   199→
   200→  /**
   201→   * 타입 파싱
   202→   * i64, string, bool 등
   203→   */
   204→  private parseType(): string {
   205→    const token = this.peek();
   206→
   207→    // 기본 타입
   208→    if (
   209→      token.type === TokenType.I64 ||
   210→      token.type === TokenType.I32 ||
   211→      token.type === TokenType.F64 ||
   212→      token.type === TokenType.BOOL ||
   213→      token.type === TokenType.STRING ||
   214→      token.type === TokenType.IDENTIFIER
   215→    ) {
   216→      return this.advance().value;
   217→    }
   218→
   219→    throw new Error(`타입 필요 at line ${token.line}`);
   220→  }
   221→
   222→  /**
   223→   * V 블록 파싱
   224→   * { statements }
   225→   */
   226→  private parseVBlock(): AST.Statement[] {
   227→    const statements: AST.Statement[] = [];
   228→
   229→    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
   230→      this.skipNewlines();
   231→
   232→      if (this.check(TokenType.RBRACE)) break;
   233→
   234→      const stmt = this.parseStatement();
   235→      if (stmt) {
   236→        statements.push(stmt);
   237→      }
   238→
   239→      this.skipNewlines();
   240→    }
   241→
   242→    return statements;
   243→  }
   244→
   245→  /**
   246→   * Python 블록 파싱
   247→   * INDENT statements DEDENT
   248→   */
   249→  private parsePyBlock(): AST.Statement[] {
   250→    const statements: AST.Statement[] = [];
   251→
   252→    this.consume(TokenType.INDENT, 'INDENT 필요');
   253→
   254→    while (!this.check(TokenType.DEDENT) && !this.isAtEnd()) {
   255→      this.skipNewlines();
   256→
   257→      if (this.check(TokenType.DEDENT) || this.isAtEnd()) break;
   258→
   259→      const stmt = this.parseStatement();
   260→      if (stmt) {
   261→        statements.push(stmt);
   262→      }
   263→
   264→      this.skipNewlines();
   265→    }
   266→
   267→    // DEDENT 또는 EOF 모두 허용 (파일 끝에서 DEDENT가 항상 생성되지 않을 수 있음)
   268→    if (this.check(TokenType.DEDENT)) {
   269→      this.advance();
   270→    }
   271→
   272→    return statements;
   273→  }
   274→
   275→  /**
   276→   * 문장 파싱
   277→   */
   278→  private parseStatement(): AST.Statement {
   279→    const token = this.peek();
   280→
   281→    // return 문장
   282→    if (token.type === TokenType.RETURN) {
   283→      return this.parseReturnStatement();
   284→    }
   285→
   286→    // if 문장
   287→    if (token.type === TokenType.IF) {
   288→      return this.parseIfStatement();
   289→    }
   290→
   291→    // while 루프
   292→    if (token.type === TokenType.WHILE) {
   293→      return this.parseWhileStatement();
   294→    }
   295→
   296→    // pass 문장 (Python)
   297→    if (token.type === TokenType.PASS) {
   298→      const passToken = this.advance();
   299→      return {
   300→        type: 'ExprStatement',
   301→        expression: {
   302→          type: 'Identifier',
   303→          name: 'pass',
   304→          line: passToken.line,
   305→          column: passToken.column,
   306→          mode: passToken.mode,
   307→        },
   308→        line: passToken.line,
   309→        column: passToken.column,
   310→        mode: passToken.mode,
   311→      };
   312→    }
   313→
   314→    // let 또는 식별자 (할당 가능성)
   315→    if (token.type === TokenType.LET || token.type === TokenType.IDENTIFIER) {
   316→      return this.parseAssignOrExpr();
   317→    }
   318→
   319→    // 기본값: 표현식 문장
   320→    const expr = this.parseExpression();
   321→    const startToken = this.peek();
   322→    return {
   323→      type: 'ExprStatement',
   324→      expression: expr,
   325→      line: startToken.line,
   326→      column: startToken.column,
   327→      mode: startToken.mode,
   328→    };
   329→  }
   330→
   331→  /**
   332→   * Return 문장 파싱
   333→   */
   334→  private parseReturnStatement(): AST.ReturnStatement {
   335→    const startToken = this.consume(TokenType.RETURN, 'return 필요');
   336→    let value: AST.Expression | undefined;
   337→
   338→    // 반환값이 있으면 파싱
   339→    if (!this.check(TokenType.NEWLINE) && !this.check(TokenType.DEDENT) && !this.check(TokenType.RBRACE)) {
   340→      value = this.parseExpression();
   341→    }
   342→
   343→    return {
   344→      type: 'Return',
   345→      value,
   346→      line: startToken.line,
   347→      column: startToken.column,
   348→      mode: startToken.mode,
   349→    };
   350→  }
   351→
   352→  /**
   353→   * 할당 또는 표현식 파싱
   354→   */
   355→  private parseAssignOrExpr(): AST.Statement {
   356→    const startToken = this.peek();
   357→
   358→    // let x = value
   359→    if (startToken.type === TokenType.LET) {
   360→      this.advance();
   361→      const nameToken = this.consume(TokenType.IDENTIFIER, '변수명 필요');
   362→      this.consume(TokenType.EQUAL, '= 필요');
   363→      const value = this.parseExpression();
   364→
   365→      return {
   366→        type: 'Assign',
   367→        name: nameToken.value,
   368→        value,
   369→        line: startToken.line,
   370→        column: startToken.column,
   371→        mode: startToken.mode,
   372→      };
   373→    }
   374→
   375→    // x = value 또는 함수호출 등
   376→    if (startToken.type === TokenType.IDENTIFIER) {
   377→      const nameToken = this.peek();
   378→      const name = nameToken.value;
   379→      this.advance();
   380→
   381→      if (this.check(TokenType.EQUAL)) {
   382→        this.advance();
   383→        const value = this.parseExpression();
   384→
   385→        return {
   386→          type: 'Assign',
   387→          name,
   388→          value,
   389→          line: startToken.line,
   390→          column: startToken.column,
   391→          mode: startToken.mode,
   392→        };
   393→      }
   394→
   395→      // 아니면 전체 표현식으로 다시 파싱 (함수호출 등 포함)
   396→      // pos를 한 칸 뒤로 이동하여 식별자부터 다시 파싱
   397→      this.pos--;
   398→      const expr = this.parseExpression();
   399→
   400→      return {
   401→        type: 'ExprStatement',
   402→        expression: expr,
   403→        line: startToken.line,
   404→        column: startToken.column,
   405→        mode: startToken.mode,
   406→      };
   407→    }
   408→
   409→    throw new Error(`예상치 못한 토큰 at line ${startToken.line}`);
   410→  }
   411→
   412→  /**
   413→   * If 문장 파싱
   414→   * if condition { body } [else { body }]
   415→   */
   416→  private parseIfStatement(): AST.IfStatement {
   417→    const startToken = this.consume(TokenType.IF, 'if 키워드 필요');
   418→    const condition = this.parseExpression();
   419→    this.consume(TokenType.LBRACE, '{ 필요');
   420→    const thenBranch = this.parseVBlock();
   421→    this.consume(TokenType.RBRACE, '} 필요');
   422→
   423→    let elseBranch: AST.Statement[] | undefined;
   424→    if (this.match(TokenType.ELSE)) {
   425→      this.consume(TokenType.LBRACE, '{ 필요');
   426→      elseBranch = this.parseVBlock();
   427→      this.consume(TokenType.RBRACE, '} 필요');
   428→    }
   429→
   430→    return {
   431→      type: 'IfStatement',
   432→      condition,
   433→      thenBranch,
   434→      elseBranch,
   435→      line: startToken.line,
   436→      column: startToken.column,
   437→      mode: startToken.mode,
   438→    };
   439→  }
   440→
   441→  /**
   442→   * While 루프 파싱
   443→   * while condition { body }
   444→   */
   445→  private parseWhileStatement(): AST.WhileStatement {
   446→    const startToken = this.consume(TokenType.WHILE, 'while 키워드 필요');
   447→    const condition = this.parseExpression();
   448→    this.consume(TokenType.LBRACE, '{ 필요');
   449→    const body = this.parseVBlock();
   450→    this.consume(TokenType.RBRACE, '} 필요');
   451→
   452→    return {
   453→      type: 'WhileStatement',
   454→      condition,
   455→      body,
   456→      line: startToken.line,
   457→      column: startToken.column,
   458→      mode: startToken.mode,
   459→    };
   460→  }
   461→
   462→  /**
   463→   * 표현식 파싱
   464→   * 간단한 구현: 곱셈/나눗셈 → 덧셈/뺄셈 → 비교/논리
   465→   */
   466→  private parseExpression(): AST.Expression {
   467→    return this.parseLogicalOr();
   468→  }
   469→
   470→  /**
   471→   * 논리 OR 파싱: ||
   472→   */
   473→  private parseLogicalOr(): AST.Expression {
   474→    let expr = this.parseLogicalAnd();
   475→
   476→    while (this.match(TokenType.OR)) {
   477→      const operator = this.previous().value;
   478→      const right = this.parseLogicalAnd();
   479→      const token = this.previous();
   480→      expr = {
   481→        type: 'BinaryExpr',
   482→        left: expr,
   483→        operator,
   484→        right,
   485→        line: token.line,
   486→        column: token.column,
   487→        mode: token.mode,
   488→      };
   489→    }
   490→
   491→    return expr;
   492→  }
   493→
   494→  /**
   495→   * 논리 AND 파싱: &&
   496→   */
   497→  private parseLogicalAnd(): AST.Expression {
   498→    let expr = this.parseEquality();
   499→
   500→    while (this.match(TokenType.AND)) {
   501→      const operator = this.previous().value;
   502→      const right = this.parseEquality();
   503→      const token = this.previous();
   504→      expr = {
   505→        type: 'BinaryExpr',
   506→        left: expr,
   507→        operator,
   508→        right,
   509→        line: token.line,
   510→        column: token.column,
   511→        mode: token.mode,
   512→      };
   513→    }
   514→
   515→    return expr;
   516→  }
   517→
   518→  /**
   519→   * 등호/부등호 파싱: ==, !=
   520→   */
   521→  private parseEquality(): AST.Expression {
   522→    let expr = this.parseComparison();
   523→
   524→    while (this.match(TokenType.EQ, TokenType.NE)) {
   525→      const operator = this.previous().value;
   526→      const right = this.parseComparison();
   527→      const token = this.previous();
   528→      expr = {
   529→        type: 'BinaryExpr',
   530→        left: expr,
   531→        operator,
   532→        right,
   533→        line: token.line,
   534→        column: token.column,
   535→        mode: token.mode,
   536→      };
   537→    }
   538→
   539→    return expr;
   540→  }
   541→
   542→  /**
   543→   * 비교 파싱: <, >, <=, >=
   544→   */
   545→  private parseComparison(): AST.Expression {
   546→    let expr = this.parseAddition();
   547→
   548→    while (this.match(TokenType.LT, TokenType.GT, TokenType.LE, TokenType.GE)) {
   549→      const operator = this.previous().value;
   550→      const right = this.parseAddition();
   551→      const token = this.previous();
   552→      expr = {
   553→        type: 'BinaryExpr',
   554→        left: expr,
   555→        operator,
   556→        right,
   557→        line: token.line,
   558→        column: token.column,
   559→        mode: token.mode,
   560→      };
   561→    }
   562→
   563→    return expr;
   564→  }
   565→
   566→  /**
   567→   * 덧셈/뺄셈 파싱
   568→   */
   569→  private parseAddition(): AST.Expression {
   570→    let expr = this.parseMultiplication();
   571→
   572→    while (this.match(TokenType.PLUS, TokenType.MINUS)) {
   573→      const operator = this.previous().value;
   574→      const right = this.parseMultiplication();
   575→      const token = this.previous();
   576→      expr = {
   577→        type: 'BinaryExpr',
   578→        left: expr,
   579→        operator,
   580→        right,
   581→        line: token.line,
   582→        column: token.column,
   583→        mode: token.mode,
   584→      };
   585→    }
   586→
   587→    return expr;
   588→  }
   589→
   590→  /**
   591→   * 곱셈/나눗셈 파싱
   592→   */
   593→  private parseMultiplication(): AST.Expression {
   594→    let expr = this.parseUnary();
   595→
   596→    while (this.match(TokenType.STAR, TokenType.SLASH)) {
   597→      const operator = this.previous().value;
   598→      const right = this.parseUnary();
   599→      const token = this.previous();
   600→      expr = {
   601→        type: 'BinaryExpr',
   602→        left: expr,
   603→        operator,
   604→        right,
   605→        line: token.line,
   606→        column: token.column,
   607→        mode: token.mode,
   608→      };
   609→    }
   610→
   611→    return expr;
   612→  }
   613→
   614→  /**
   615→   * 단항 연산 파싱
   616→   */
   617→  private parseUnary(): AST.Expression {
   618→    // TODO: 단항 연산자 (-, !, ~) 처리 가능
   619→    return this.parsePostfix();
   620→  }
   621→
   622→  /**
   623→   * 후위 연산 파싱 (함수 호출, 배열 접근)
   624→   */
   625→  private parsePostfix(): AST.Expression {
   626→    let expr = this.parsePrimary();
   627→
   628→    while (true) {
   629→      // 함수 호출: foo()
   630→      if (this.match(TokenType.LPAREN)) {
   631→        const args = this.parseArguments();
   632→        this.consume(TokenType.RPAREN, ') 필요');
   633→
   634→        const token = this.previous();
   635→        expr = {
   636→          type: 'Call',
   637→          callee: expr,
   638→          args,
   639→          line: token.line,
   640→          column: token.column,
   641→          mode: token.mode,
   642→        };
   643→      }
   644→      // 배열 인덱싱: arr[0]
   645→      else if (this.match(TokenType.LBRACKET)) {
   646→        const index = this.parseExpression();
   647→        const token = this.consume(TokenType.RBRACKET, '] 필요');
   648→
   649→        expr = {
   650→          type: 'ArrayAccess',
   651→          object: expr,
   652→          index,
   653→          line: token.line,
   654→          column: token.column,
   655→          mode: token.mode,
   656→        };
   657→      }
   658→      // 멤버 접근: obj.property
   659→      else if (this.match(TokenType.DOT)) {
   660→        const propToken = this.consume(TokenType.IDENTIFIER, '프로퍼티명 필요');
   661→        const token = this.previous();
   662→
   663→        expr = {
   664→          type: 'MemberAccess',
   665→          object: expr,
   666→          property: propToken.value,
   667→          line: token.line,
   668→          column: token.column,
   669→          mode: token.mode,
   670→        };
   671→      } else {
   672→        break;
   673→      }
   674→    }
   675→
   676→    return expr;
   677→  }
   678→
   679→  /**
   680→   * 기본 표현식 파싱 (리터럴, 식별자 등)
   681→   */
   682→  private parsePrimary(): AST.Expression {
   683→    const token = this.peek();
   684→
   685→    // 숫자
   686→    if (token.type === TokenType.NUMBER) {
   687→      this.advance();
   688→      return {
   689→        type: 'Number',
   690→        value: token.value,
   691→        line: token.line,
   692→        column: token.column,
   693→        mode: token.mode,
   694→      };
   695→    }
   696→
   697→    // 문자열
   698→    if (token.type === TokenType.STRING) {
   699→      this.advance();
   700→      return {
   701→        type: 'String',
   702→        value: token.value,
   703→        line: token.line,
   704→        column: token.column,
   705→        mode: token.mode,
   706→      };
   707→    }
   708→
   709→    // true, false
   710→    if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
   711→      this.advance();
   712→      return {
   713→        type: 'Number',
   714→        value: token.type === TokenType.TRUE ? 1 : 0,
   715→        line: token.line,
   716→        column: token.column,
   717→        mode: token.mode,
   718→      };
   719→    }
   720→
   721→    // 배열 리터럴: [1, 2, 3]
   722→    if (token.type === TokenType.LBRACKET) {
   723→      return this.parseArrayLiteral();
   724→    }
   725→
   726→    // 식별자
   727→    if (token.type === TokenType.IDENTIFIER) {
   728→      this.advance();
   729→      return {
   730→        type: 'Identifier',
   731→        name: token.value,
   732→        line: token.line,
   733→        column: token.column,
   734→        mode: token.mode,
   735→      };
   736→    }
   737→
   738→    // 괄호 식
   739→    if (this.match(TokenType.LPAREN)) {
   740→      const expr = this.parseExpression();
   741→      this.consume(TokenType.RPAREN, ') 필요');
   742→      return expr;
   743→    }
   744→
   745→    throw new Error(`예상치 못한 토큰: ${token.value} at line ${token.line}`);
   746→  }
   747→
   748→  /**
   749→   * 배열 리터럴 파싱
   750→   * [1, 2, 3], [], [a+b, c*d], [1, 2,] (trailing comma 지원)
   751→   */
   752→  private parseArrayLiteral(): AST.ArrayLiteral {
   753→    const startToken = this.consume(TokenType.LBRACKET, '[');
   754→    const elements: AST.Expression[] = [];
   755→
   756→    // 빈 배열 또는 요소들
   757→    while (!this.check(TokenType.RBRACKET) && !this.isAtEnd()) {
   758→      elements.push(this.parseExpression());
   759→
   760→      // 쉼표가 있으면 계속, 없으면 종료
   761→      if (!this.match(TokenType.COMMA)) {
   762→        break;
   763→      }
   764→
   765→      // trailing comma: 쉼표 뒤에 ] 가 있으면 즉시 종료
   766→      if (this.check(TokenType.RBRACKET)) {
   767→        break;
   768→      }
   769→    }
   770→
   771→    const endToken = this.consume(TokenType.RBRACKET, '] 필요');
   772→
   773→    return {
   774→      type: 'Array',
   775→      elements,
   776→      line: startToken.line,
   777→      column: startToken.column,
   778→      mode: startToken.mode,
   779→    };
   780→  }
   781→
   782→  /**
   783→   * 함수 호출 인자 파싱
   784→   */
   785→  private parseArguments(): AST.Expression[] {
   786→    const args: AST.Expression[] = [];
   787→
   788→    if (!this.check(TokenType.RPAREN)) {
   789→      do {
   790→        args.push(this.parseExpression());
   791→      } while (this.match(TokenType.COMMA));
   792→    }
   793→
   794→    return args;
   795→  }
   796→
   797→  // ========== 헬퍼 메서드 ==========
   798→
   799→  private peek(): Token {
   800→    if (this.pos >= this.tokens.length) {
   801→      return this.tokens[this.tokens.length - 1]; // EOF 토큰
   802→    }
   803→    return this.tokens[this.pos];
   804→  }
   805→
   806→  private advance(): Token {
   807→    if (!this.isAtEnd()) {
   808→      this.pos++;
   809→    }
   810→    return this.previous();
   811→  }
   812→
   813→  private previous(): Token {
   814→    return this.tokens[this.pos - 1];
   815→  }
   816→
   817→  private isAtEnd(): boolean {
   818→    return this.peek().type === TokenType.EOF;
   819→  }
   820→
   821→  private check(type: TokenType): boolean {
   822→    if (this.isAtEnd()) return false;
   823→    return this.peek().type === type;
   824→  }
   825→
   826→  private match(...types: TokenType[]): boolean {
   827→    for (const type of types) {
   828→      if (this.check(type)) {
   829→        this.advance();
   830→        return true;
   831→      }
   832→    }
   833→    return false;
   834→  }
   835→
   836→  private consume(type: TokenType, message: string): Token {
   837→    if (this.check(type)) return this.advance();
   838→
   839→    const token = this.peek();
   840→    throw new Error(`${message} at line ${token.line}, got ${token.value}`);
   841→  }
   842→
   843→  private skipNewlines(): void {
   844→    while (this.match(TokenType.NEWLINE)) {
   845→      // 계속
   846→    }
   847→  }
   848→}
