     1→/**
     2→ * FreeLang Nexus - 코드 생성기
     3→ * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
     4→ */
     5→
     6→import * as AST from '../parser/ast';
     7→
     8→export interface CodegenResult {
     9→  c: string;       // V 모드 함수들 → C 코드
    10→  python: string;  // Python 모드 함수들 → Python 코드
    11→  mixed: string;   // 두 코드 주석으로 구분 (디버그용)
    12→}
    13→
    14→export class NexusCodegen {
    15→  private cLines: string[] = [];
    16→  private pyLines: string[] = [];
    17→  private indentLevel: number = 0;
    18→
    19→  /**
    20→   * V 모드 내장 함수 처리
    21→   */
    22→  private readonly V_BUILTINS = new Set(['println', 'print', 'len', 'to_string', 'int_cast']);
    23→
    24→  /**
    25→   * 프로그램 전체 코드 생성
    26→   */
    27→  generate(program: AST.Program): CodegenResult {
    28→    // @mode 마커는 무시하고 함수/문장만 처리
    29→    for (const item of program.body) {
    30→      const fnItem = item as any;
    31→      if (fnItem.type === 'VFunction') {
    32→        this.genVFunction(fnItem as AST.VFunction);
    33→      } else if (fnItem.type === 'PyFunction') {
    34→        this.genPyFunction(fnItem as AST.PyFunction);
    35→      } else if (fnItem.type === 'Return' || fnItem.type === 'Assign' || fnItem.type === 'ExprStatement') {
    36→        // 탑레벨 문장은 V 모드(C)로 처리
    37→        this.genVStatement(fnItem as AST.Statement);
    38→      }
    39→    }
    40→
    41→    const c = this.cLines.join('\n');
    42→    const python = this.pyLines.join('\n');
    43→
    44→    // mixed: 두 언어 코드를 주석으로 구분해서 출력 (확인용)
    45→    const mixed =
    46→      c && python
    47→        ? `/* ===== V (C) ===== */\n${c}\n\n/* ===== Python ===== */\n# (Not valid C, just for reference)\n${python}`
    48→        : c || python;
    49→
    50→    return { c, python, mixed };
    51→  }
    52→
    53→  /**
    54→   * 실행 가능한 프로그램 생성
    55→   * C에는 #include + main() 추가, Python에는 if __name__ 추가
    56→   */
    57→  generateProgram(program: AST.Program): CodegenResult {
    58→    const base = this.generate(program);
    59→
    60→    // C 코드에 헤더 + main() wrapping 추가
    61→    const cWithMain = base.c
    62→      ? `#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n#include <stdlib.h>\n\n${base.c}\nint main() {\n    return 0;\n}\n`
    63→      : '';
    64→
    65→    // Python 코드에 main 블록 추가
    66→    const pyWithMain = base.python
    67→      ? `${base.python}\n\nif __name__ == '__main__':\n    pass\n`
    68→      : '';
    69→
    70→    return {
    71→      c: cWithMain,
    72→      python: pyWithMain,
    73→      mixed: base.mixed,
    74→    };
    75→  }
    76→
    77→  /**
    78→   * V 함수 → C 함수
    79→   * fn add(x: i64, y: i64) -> i64 { return x + y }
    80→   * →
    81→   * long long add(long long x, long long y) { return x + y; }
    82→   */
    83→  private genVFunction(fn: AST.VFunction): void {
    84→    // 반환타입
    85→    const returnType = this.mapVType(fn.returnType || 'void');
    86→
    87→    // 파라미터 리스트
    88→    const paramList = fn.params.map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`).join(', ');
    89→
    90→    // 함수 시그니처
    91→    this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
    92→
    93→    // 함수 본문
    94→    this.indentLevel++;
    95→    for (const stmt of fn.body) {
    96→      this.genVStatement(stmt);
    97→    }
    98→    this.indentLevel--;
    99→
   100→    this.writeC('}');
   101→    this.writeC(''); // 빈 줄
   102→  }
   103→
   104→  /**
   105→   * Python 함수 → Python 함수
   106→   * def slow(items): return items
   107→   * →
   108→   * def slow(items):
   109→   *     return items
   110→   */
   111→  private genPyFunction(fn: AST.PyFunction): void {
   112→    // 파라미터 리스트
   113→    const paramList = fn.params.map((p) => p.name).join(', ');
   114→
   115→    // 함수 정의
   116→    this.writePy(`def ${fn.name}(${paramList}):`);
   117→
   118→    // 함수 본문 (들여쓰기 필요)
   119→    this.indentLevel++;
   120→    for (const stmt of fn.body) {
   121→      this.genPyStatement(stmt);
   122→    }
   123→    this.indentLevel--;
   124→
   125→    this.writePy(''); // 빈 줄
   126→  }
   127→
   128→  /**
   129→   * V 문장 생성 (C 코드용)
   130→   */
   131→  private genVStatement(stmt: AST.Statement): void {
   132→    const s = stmt as any;
   133→
   134→    if (s.type === 'Return') {
   135→      const returnStmt = s as AST.ReturnStatement;
   136→      if (returnStmt.value) {
   137→        const expr = this.genVExpression(returnStmt.value);
   138→        this.writeC(`${this.indent()}return ${expr};`);
   139→      } else {
   140→        this.writeC(`${this.indent()}return;`);
   141→      }
   142→    } else if (s.type === 'Assign') {
   143→      const assignStmt = s as AST.AssignStatement;
   144→      const expr = this.genVExpression(assignStmt.value);
   145→      // 값의 타입에 따라 C 타입 결정
   146→      const value = assignStmt.value as any;
   147→      let cType = 'long long'; // 기본값
   148→      if (value.type === 'String') {
   149→        cType = 'char*'; // 문자열 리터럴
   150→      }
   151→      this.writeC(`${this.indent()}${cType} ${assignStmt.name} = ${expr};`);
   152→    } else if (s.type === 'ExprStatement') {
   153→      const exprStmt = s as AST.ExprStatement;
   154→      const expr = this.genVExpression(exprStmt.expression);
   155→      this.writeC(`${this.indent()}${expr};`);
   156→    } else if (s.type === 'IfStatement') {
   157→      const ifStmt = s as AST.IfStatement;
   158→      const cond = this.genVExpression(ifStmt.condition);
   159→      this.writeC(`${this.indent()}if (${cond}) {`);
   160→      this.indentLevel++;
   161→      for (const stmt of ifStmt.thenBranch) {
   162→        this.genVStatement(stmt);
   163→      }
   164→      this.indentLevel--;
   165→      this.writeC(`${this.indent()}}`);
   166→      if (ifStmt.elseBranch) {
   167→        this.writeC(`${this.indent()}else {`);
   168→        this.indentLevel++;
   169→        for (const stmt of ifStmt.elseBranch) {
   170→          this.genVStatement(stmt);
   171→        }
   172→        this.indentLevel--;
   173→        this.writeC(`${this.indent()}}`);
   174→      }
   175→    } else if (s.type === 'WhileStatement') {
   176→      const whileStmt = s as AST.WhileStatement;
   177→      const cond = this.genVExpression(whileStmt.condition);
   178→      this.writeC(`${this.indent()}while (${cond}) {`);
   179→      this.indentLevel++;
   180→      for (const stmt of whileStmt.body) {
   181→        this.genVStatement(stmt);
   182→      }
   183→      this.indentLevel--;
   184→      this.writeC(`${this.indent()}}`);
   185→    }
   186→  }
   187→
   188→  /**
   189→   * Python 문장 생성 (Python 코드용)
   190→   */
   191→  private genPyStatement(stmt: AST.Statement): void {
   192→    const s = stmt as any;
   193→    const indentStr = this.indent();
   194→
   195→    if (s.type === 'Return') {
   196→      const returnStmt = s as AST.ReturnStatement;
   197→      if (returnStmt.value) {
   198→        const expr = this.genPyExpression(returnStmt.value);
   199→        this.writePy(`${indentStr}return ${expr}`);
   200→      } else {
   201→        this.writePy(`${indentStr}return`);
   202→      }
   203→    } else if (s.type === 'Assign') {
   204→      const assignStmt = s as AST.AssignStatement;
   205→      const expr = this.genPyExpression(assignStmt.value);
   206→      this.writePy(`${indentStr}${assignStmt.name} = ${expr}`);
   207→    } else if (s.type === 'ExprStatement') {
   208→      const exprStmt = s as AST.ExprStatement;
   209→      const expr = this.genPyExpression(exprStmt.expression);
   210→      this.writePy(`${indentStr}${expr}`);
   211→    } else if (s.type === 'WhileStatement') {
   212→      const whileStmt = s as AST.WhileStatement;
   213→      const cond = this.genPyExpression(whileStmt.condition);
   214→      this.writePy(`${indentStr}while ${cond}:`);
   215→      this.indentLevel++;
   216→      for (const stmt of whileStmt.body) {
   217→        this.genPyStatement(stmt);
   218→      }
   219→      this.indentLevel--;
   220→    }
   221→  }
   222→
   223→  /**
   224→   * V 표현식 생성 (C 코드용)
   225→   */
   226→  private genVExpression(expr: AST.Expression): string {
   227→    const e = expr as any;
   228→
   229→    if (e.type === 'Number') {
   230→      return (e as AST.NumberLiteral).value.toString();
   231→    }
   232→
   233→    if (e.type === 'String') {
   234→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
   235→      return (e as AST.StringLiteral).value;
   236→    }
   237→
   238→    if (e.type === 'Identifier') {
   239→      return (e as AST.Identifier).name;
   240→    }
   241→
   242→    if (e.type === 'BinaryExpr') {
   243→      const binExpr = e as AST.BinaryExpr;
   244→      const left = this.genVExpression(binExpr.left);
   245→      const right = this.genVExpression(binExpr.right);
   246→      return `${left} ${binExpr.operator} ${right}`;
   247→    }
   248→
   249→    if (e.type === 'Array') {
   250→      const arrayLit = e as AST.ArrayLiteral;
   251→      const elements = arrayLit.elements.map((el) => this.genVExpression(el)).join(', ');
   252→      return `{${elements}}`;
   253→    }
   254→
   255→    if (e.type === 'ArrayAccess') {
   256→      const arrayAccess = e as AST.ArrayAccess;
   257→      const obj = this.genVExpression(arrayAccess.object);
   258→      const idx = this.genVExpression(arrayAccess.index);
   259→      return `${obj}[${idx}]`;
   260→    }
   261→
   262→    if (e.type === 'Call') {
   263→      const callExpr = e as AST.CallExpr;
   264→
   265→      // callee가 Identifier인 경우 함수명 추출
   266→      let calleeStr: string | null = null;
   267→      if (typeof callExpr.callee === 'string') {
   268→        calleeStr = callExpr.callee;
   269→      } else {
   270→        const calleeExpr = callExpr.callee as any;
   271→        if (calleeExpr.type === 'Identifier') {
   272→          calleeStr = calleeExpr.name;
   273→        }
   274→      }
   275→
   276→      // V 내장 함수 처리
   277→      if (calleeStr && this.V_BUILTINS.has(calleeStr)) {
   278→        return this.genVBuiltinCall(calleeStr, callExpr.args);
   279→      }
   280→
   281→      // 일반 함수 호출
   282→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genVExpression(callExpr.callee);
   283→      const args = callExpr.args.map((arg) => this.genVExpression(arg)).join(', ');
   284→      return `${callee}(${args})`;
   285→    }
   286→
   287→    if (e.type === 'MemberAccess') {
   288→      const ma = e as AST.MemberAccess;
   289→      const obj = this.genVExpression(ma.object);
   290→      if (ma.property === 'length') {
   291→        // C에는 .length가 없으므로 sizeof 패턴 생성
   292→        return `(sizeof(${obj})/sizeof(${obj}[0]))`;
   293→      }
   294→      return `${obj}.${ma.property}`;
   295→    }
   296→
   297→    return '';
   298→  }
   299→
   300→  /**
   301→   * V 모드 내장 함수 호출 생성
   302→   */
   303→  private genVBuiltinCall(name: string, args: AST.Expression[]): string {
   304→    if (name === 'println') {
   305→      if (args.length === 0) return 'printf("\\n")';
   306→      const firstArg = args[0] as any;
   307→      // StringLiteral인 경우: printf의 format string으로 사용
   308→      if (firstArg.type === 'String') {
   309→        // firstArg.value는 "text" 형태이므로 따옴표 제거
   310→        const str = firstArg.value.slice(1, -1);
   311→        return `printf("${str}\\n")`;
   312→      }
   313→      // 숫자/식별자인 경우 %lld 포맷 사용
   314→      const arg = this.genVExpression(firstArg);
   315→      return `printf("%lld\\n", ${arg})`;
   316→    }
   317→
   318→    if (name === 'print') {
   319→      if (args.length === 0) return 'printf("")';
   320→      const firstArg = args[0] as any;
   321→      if (firstArg.type === 'String') {
   322→        // StringLiteral인 경우: printf의 format string으로 사용
   323→        const str = firstArg.value.slice(1, -1);
   324→        return `printf("${str}")`;
   325→      }
   326→      const arg = this.genVExpression(firstArg);
   327→      return `printf("%lld", ${arg})`;
   328→    }
   329→
   330→    if (name === 'len') {
   331→      const firstArg = args[0] as any;
   332→      if (firstArg.type === 'String') {
   333→        // StringLiteral인 경우 따옴표 제거
   334→        const str = firstArg.value.slice(1, -1);
   335→        return `strlen("${str}")`;
   336→      }
   337→      const arg = this.genVExpression(firstArg);
   338→      return `strlen(${arg})`;
   339→    }
   340→
   341→    if (name === 'to_string') {
   342→      const arg = this.genVExpression(args[0]);
   343→      return arg; // 단순 pass-through
   344→    }
   345→
   346→    if (name === 'int_cast') {
   347→      const firstArg = args[0] as any;
   348→      if (firstArg.type === 'String') {
   349→        const str = firstArg.value.slice(1, -1);
   350→        return `atoi("${str}")`;
   351→      }
   352→      const arg = this.genVExpression(firstArg);
   353→      return `atoi(${arg})`;
   354→    }
   355→
   356→    return '';
   357→  }
   358→
   359→  /**
   360→   * Python 표현식 생성 (Python 코드용)
   361→   */
   362→  private genPyExpression(expr: AST.Expression): string {
   363→    const e = expr as any;
   364→
   365→    if (e.type === 'Number') {
   366→      return (e as AST.NumberLiteral).value.toString();
   367→    }
   368→
   369→    if (e.type === 'String') {
   370→      // StringLiteral.value는 이미 따옴표를 포함 ("text" 형태)
